import { CheckCircle2, Clock3, Search, XCircle } from "lucide-react";
import { useMemo, useState } from "react";
import { eventDate, eventMoney, eventRequest } from "../../services/eventApi";
import "./EventBookings.css";
export default function EventBookings({bookings,search,reload}){const [filter,setFilter]=useState("");const counts={confirmed:bookings.filter(x=>x.booking_status==="confirmed").length,pending:bookings.filter(x=>x.booking_status==="pending").length,cancelled:bookings.filter(x=>x.booking_status==="cancelled").length};const rows=useMemo(()=>bookings.filter(b=>(!filter||b.booking_status===filter)&&(!search||[b.id,b.customer_name,b.event_name].some(x=>String(x||"").toLowerCase().includes(search.toLowerCase())))),[bookings,filter,search]);const update=async(id,status)=>{try{await eventRequest(`/vendor/events/bookings/${id}/status`,{method:"PATCH",body:{status}});reload()}catch(e){alert(e.response?.data?.message||e.message)}};return <section><header className="eb-title"><div><small>LIVE BOOKINGS</small><h1>Event Bookings</h1><p>Track ticket purchases and booking status.</p></div><select value={filter} onChange={e=>setFilter(e.target.value)}><option value="">All bookings</option><option>confirmed</option><option>pending</option><option>cancelled</option><option>completed</option></select></header><section className="eb-cards">{[["Confirmed",counts.confirmed,CheckCircle2,"confirmed"],["Pending",counts.pending,Clock3,"pending"],["Cancelled",counts.cancelled,XCircle,"cancelled"]].map(([l,v,I,c])=><article className={c} key={l}><I/><div><small>{l}</small><h2>{v}</h2></div></article>)}</section><article className="ed-panel ed-table-wrap"><table><thead><tr><th>Booking ID</th><th>Customer Name</th><th>Event Name</th><th>Tickets</th><th>Amount</th><th>Payment Status</th><th>Booking Status</th><th>Date</th><th>QR Status</th><th>Action</th></tr></thead><tbody>{rows.map(b=><tr key={b.id}><td>{b.id}</td><td><b>{b.customer_name}</b><small className="eb-email">{b.customer_email}</small></td><td>{b.event_name}</td><td>{b.quantity}</td><td>{eventMoney(b.total_amount)}</td><td><span className={`ed-status ${b.payment_status}`}>{b.payment_status}</span></td><td><span className={`ed-status ${b.booking_status}`}>{b.booking_status}</span></td><td>{eventDate(b.created_at)}</td><td><span className={`ed-status ${b.booking_status==="cancelled"?"cancelled":"active"}`}>{b.booking_status==="cancelled"?"Void":"Active"}</span></td><td><select value={b.booking_status} onChange={e=>update(b.id,e.target.value)}><option>pending</option><option>confirmed</option><option>cancelled</option><option>completed</option></select></td></tr>)}</tbody></table>{!rows.length&&<div className="ed-empty"><Search size={22}/> No bookings found.</div>}</article></section>}
